/**
 * One step of a robot brain, published as a ``brain.step`` event so the web app can show what each robot is
 * thinking. The fake (scripted) brain emits the same tool sequence with ``model='scripted'``.
 */
export interface BrainStep {
  camera_id: string | null;
  duration_ms: number;
  goal_id: string | null;
  input: {
    [k: string]: unknown;
  };
  kind: "thought" | "tool_call" | "tool_result" | "observation" | "message" | "status" | "error";
  /**
   * 'claude-sonnet-5-5' / 'scripted'.
   */
  model: string | null;
  /**
   * kind='observation': what the camera saw.
   */
  observation: VisionObservation | null;
  ok: boolean;
  /**
   * Tool result (JSON-able, kept small; frames are never inlined).
   */
  output: {
    [k: string]: unknown;
  };
  robot_id: string;
  role: "robot" | "user" | "system";
  step_id: string;
  /**
   * Per-robot step counter (1-based once published). NOT the bus seq (event envelope).
   */
  step_no: number;
  store_id: string | null;
  /**
   * Thought / message text, or a one-line summary of the tool call/result.
   */
  text: string;
  /**
   * One of contracts.tools.BRAIN_TOOL_NAMES for tool_call/tool_result.
   */
  tool: string | null;
  tool_use_id: string | null;
  trip_id: string | null;
  ts: string;
}
/**
 * Answer of ``CameraService.observe`` (the robot brain's ``look`` tool, POST /api/cameras/{id}/observe).
 *
 * Computed from a face-BLURRED frame. Real: ``claude-haiku-5-5`` vision via utils.llm (+ ground truth hints in
 * sim); fake: built from the frame's ground-truth ``instances``.
 */
export interface VisionObservation {
  /**
   * Natural-language description / answer to the question.
   */
  answer: string;
  /**
   * Always True: observations are made on blurred frames only.
   */
  blurred: boolean;
  camera_id: string;
  frame_id: string | null;
  goal_id: string | null;
  items: ObservedItem[];
  latency_ms: number;
  method: "vlm" | "ground_truth" | "cv" | "fake";
  /**
   * Vision model id when method='vlm'.
   */
  model: string | null;
  observation_id: string;
  /**
   * People (faces) seen; their faces were blurred before analysis.
   */
  people: number;
  /**
   * What was asked ('Is the mild salsa in stock?'); None = describe.
   */
  question: string | null;
  robot_id: string | null;
  store_id: string | null;
  ts: string;
}
/**
 * One thing the vision step saw in a frame.
 */
export interface ObservedItem {
  bbox: BBox | null;
  confidence: number;
  count: number;
  /**
   * Produce only: 1.0 = perfectly fresh.
   */
  freshness: number | null;
  /**
   * What it is, in words: 'Casa Verde Mild Salsa 16 oz jar'.
   */
  label: string;
  /**
   * Price read off the shelf tag next to it, if any.
   */
  shelf_tag_cents: number | null;
  /**
   * Catalog SKU when identified.
   */
  sku: string | null;
  slot_id: string | null;
}
export interface StockUpdated {
  level: StockLevel;
  movement: StockMovement | null;
  /**
   * NL request it stems from (filter key).
   */
  request_id: string | null;
  /**
   * Robot the event is about (filter key).
   */
  robot_id: string | null;
  /**
   * Assigned by the publisher; 0 = not yet published.
   */
  seq: number;
  /**
   * Producing arm, e.g. 'gateway', 'robot'.
   */
  source: string | null;
  /**
   * Store the event is about (filter key).
   */
  store_id: string | null;
  /**
   * Trip it belongs to (filter key). Shop-goal events MUST carry goal.trip_id; None only for store/fleet-level events (stock, non-shop goals, robots) and request.*.
   */
  trip_id: string | null;
  ts: string;
  type: "stock.updated";
  /**
   * User it is for (filter key; Trip/Goal/RequestPlan.user_id).
   */
  user_id: string | null;
}
/**
 * Current stock of one SKU in one store, aggregated over its slots (GET /api/stores/{id}/stock).
 */
export interface StockLevel {
  /**
   * Where the first slot is, e.g. 'Aisle 3'.
   */
  aisle_label: string | null;
  brand: string | null;
  /**
   * Max units (sum of Slot.capacity).
   */
  capacity: number;
  category: string;
  fill_ratio: number;
  /**
   * Product.image_url (display).
   */
  image_url: string | null;
  last_movement_at: string | null;
  last_scan_at: string | null;
  /**
   * qty <= this -> 'low' (sum of the slots' thresholds).
   */
  low_threshold: number;
  name: string;
  /**
   * Units in lots expiring within 3 days.
   */
  near_expiry_qty: number;
  /**
   * Effective unit price in this store (deal applied).
   */
  price_cents: number | null;
  /**
   * Units on the shelf now (sum over slots).
   */
  qty: number;
  /**
   * Product.size, e.g. '16 oz' (display).
   */
  size: string | null;
  sku: string;
  slot_ids: string[];
  status: "ok" | "low" | "out";
  store_id: string;
  subcategory: string | null;
  /**
   * Product.unit (display).
   */
  unit: string;
}
/**
 * One row of the append-only stock history (GET /api/stores/{id}/stock/history[?sku]).
 */
export interface StockMovement {
  actor: string;
  /**
   * Signed units actually applied.
   */
  delta: number;
  lot_id: string | null;
  movement_id: string;
  note: string;
  qty_after: number;
  /**
   * SKU qty in the store before (sum over slots).
   */
  qty_before: number;
  reason: "pick" | "scan" | "restock" | "damage" | "manual";
  ref_id: string | null;
  sku: string;
  slot_id: string | null;
  store_id: string;
  ts: string;
}
/**
 * A SKU went low/out (``alert.active``) or was restocked back to ok (``alert.active=False``).
 */
export interface StockAlertEvent {
  alert: StockAlert;
  /**
   * NL request it stems from (filter key).
   */
  request_id: string | null;
  /**
   * Robot the event is about (filter key).
   */
  robot_id: string | null;
  /**
   * Assigned by the publisher; 0 = not yet published.
   */
  seq: number;
  /**
   * Producing arm, e.g. 'gateway', 'robot'.
   */
  source: string | null;
  /**
   * Store the event is about (filter key).
   */
  store_id: string | null;
  /**
   * Trip it belongs to (filter key). Shop-goal events MUST carry goal.trip_id; None only for store/fleet-level events (stock, non-shop goals, robots) and request.*.
   */
  trip_id: string | null;
  ts: string;
  type: "stock.alert";
  /**
   * User it is for (filter key; Trip/Goal/RequestPlan.user_id).
   */
  user_id: string | null;
}
/**
 * A SKU that went low / out in a store (GET /api/stores/{id}/stock/alerts lists the active ones).
 */
export interface StockAlert {
  /**
   * False once restocked back to 'ok' (sent once as a clear).
   */
  active: boolean;
  actor: string | null;
  aisle_label: string | null;
  /**
   * Stable per store+sku: f'{store_id}:{sku}'.
   */
  alert_id: string;
  capacity: number;
  category: string | null;
  cleared_at: string | null;
  /**
   * Product.image_url (display).
   */
  image_url: string | null;
  low_threshold: number;
  /**
   * Staff-facing, e.g. 'Casa Verde Mild Salsa is out of stock (Aisle 3)'.
   */
  message: string;
  name: string;
  qty: number;
  raised_at: string;
  /**
   * Product.size (display).
   */
  size: string | null;
  sku: string;
  slot_ids: string[];
  status: "low" | "out";
  store_id: string;
  /**
   * capacity - qty.
   */
  suggested_restock_qty: number;
  /**
   * What caused it (a robot scan, a pick, ...).
   */
  trigger: ("pick" | "scan" | "restock" | "damage" | "manual") | null;
  /**
   * Product.unit (display).
   */
  unit: string;
}
export interface AgentMessage {
  channel: ("web" | "voice" | "photon") | null;
  /**
   * Streaming: the newly appended chunk.
   */
  delta: string | null;
  done: boolean;
  message_id: string;
  /**
   * NL request it stems from (filter key).
   */
  request_id: string | null;
  /**
   * Robot the event is about (filter key).
   */
  robot_id: string | null;
  role: "user" | "assistant" | "system" | "tool";
  /**
   * Assigned by the publisher; 0 = not yet published.
   */
  seq: number;
  /**
   * Producing arm, e.g. 'gateway', 'robot'.
   */
  source: string | null;
  /**
   * Store the event is about (filter key).
   */
  store_id: string | null;
  /**
   * Full text so far (or final text when done).
   */
  text: string;
  /**
   * Trip it belongs to (filter key). Shop-goal events MUST carry goal.trip_id; None only for store/fleet-level events (stock, non-shop goals, robots) and request.*.
   */
  trip_id: string | null;
  ts: string;
  type: "agent.message";
  /**
   * User it is for (filter key; Trip/Goal/RequestPlan.user_id).
   */
  user_id: string | null;
}
export interface ErrorEvent {
  arm: string;
  code: string | null;
  message: string;
  recoverable: boolean;
  /**
   * NL request it stems from (filter key).
   */
  request_id: string | null;
  /**
   * Robot the event is about (filter key).
   */
  robot_id: string | null;
  /**
   * Assigned by the publisher; 0 = not yet published.
   */
  seq: number;
  /**
   * Producing arm, e.g. 'gateway', 'robot'.
   */
  source: string | null;
  /**
   * Store the event is about (filter key).
   */
  store_id: string | null;
  /**
   * Trip it belongs to (filter key). Shop-goal events MUST carry goal.trip_id; None only for store/fleet-level events (stock, non-shop goals, robots) and request.*.
   */
  trip_id: string | null;
  ts: string;
  type: "error";
  /**
   * User it is for (filter key; Trip/Goal/RequestPlan.user_id).
   */
  user_id: string | null;
}
